namespace Aspose.Pdf.Text;

/// <summary>
/// Self-contained Big5 (codepage 950 / Adobe-CNS1, Traditional Chinese) two-byte
/// code -> Unicode table. Lets the extractor and renderer decode text from
/// non-embedded predefined Big5 CMaps (ETen-B5-H, B5pc-H, ...) and Big5-encoded
/// /BaseFont names without depending on the System.Text.Encoding.CodePages
/// package. Generated from the standard cp950 mapping. Trail bytes cover
/// 0x40-0x7E and 0xA1-0xFE (157 per lead); leads cover 0x81-0xFE.
/// </summary>
internal static class Big5Table
{
    private static ushort[]? _table;
    private static ushort[] Table => _table ??= Decode(Data);

    /// <summary>Big5 byte-code -> Unicode codepoint, or null when unmapped.</summary>
    public static int? ToUnicode(int code)
    {
        if (code <= 0x7F) return code;            // ASCII single byte
        int lead = code >> 8, trail = code & 0xFF;
        if (lead < 0x81 || lead > 0xFE) return null;
        int ti;
        if (trail >= 0x40 && trail <= 0x7E) ti = trail - 0x40;
        else if (trail >= 0xA1 && trail <= 0xFE) ti = 63 + (trail - 0xA1);
        else return null;
        var u = Table[(lead - 0x81) * 157 + ti];
        return u == 0 ? (int?)null : u;
    }

    private static ushort[] Decode(string b64)
    {
        var raw = System.Convert.FromBase64String(b64);
        var r = new ushort[raw.Length / 2];
        for (int i = 0; i < r.Length; i++)
            r[i] = (ushort)(raw[i * 2] | (raw[i * 2 + 1] << 8));
        return r;
    }

